/**
 * The Inwire mark: two nested chevrons, each drawn as one folded band.
 *
 * A band of constant width, folded once, seen from an angle - and a second,
 * smaller one tucked inside it. It reads as direction of travel twice over,
 * which is what the app watches: traffic going somewhere, at two scales.
 *
 * **Constant width is the whole trick.** The band is not drawn by placing
 * vertices; it is generated by offsetting a centreline to both sides and
 * mitring the joint. A hand-drawn fold narrows where it turns, because the
 * naive offset shortens the inside of the corner, and that pinch is the single
 * thing that makes a hand-drawn ribbon look wrong at large sizes. Mitring puts
 * the corner where the two offset edges actually intersect, so the band is the
 * same width through the turn as it is along the straight.
 *
 * **How it survives being shrunk.** Each straight run is its own quad at its
 * own opacity, so the folds read as planes turned at different angles to a
 * light. That is decoration, not structure: flattened to a single tone - which
 * is what a 16px tab and the `.ico` actually render - the two chevrons are
 * still two separated shapes, because they are held apart by real negative
 * space rather than by a change in tone. Marks that fail at 16px fail because
 * their detail is load-bearing; here none of it is.
 *
 * **Why this is a module and not several drawings.** The mark has to exist as
 * JSX for the header and as markup in `public/icon.svg` for the browser tab,
 * and two hand-authored copies of one shape are two things that drift. It is
 * computed once, here; `BrandMark.tsx` renders these paths and
 * `scripts/brand/render-icons.ts` writes every file from the identical call, so
 * `scripts/brand/icon.ts` only has to check the committed files still match.
 *
 * No React and no DOM, so the scripts can import it under `tsx` - the same
 * constraint `services/dashboardPrefs.ts` documents for the same reason.
 */

/** The drawing grid. Square, and halves cleanly to a 16px favicon. */
export const MARK_SIZE = 32;

type Point = readonly [number, number];

const R = (n: number) => Math.round(n * 100) / 100;

/**
 * The two chevrons, as centrelines and band widths.
 *
 * The arms reach as close to the edges as the mitre allows, on purpose. A mark
 * floating in the middle of its own box looks small at every size it is ever
 * drawn at, and there is no way for the header or the tab to make up the
 * difference - they can only scale the box. These numbers put the drawn mark at
 * about 86% of the box across and 90% down, centred on both axes;
 * `scripts/brand/icon.ts` holds that as a floor so a later tweak cannot quietly
 * shrink it.
 *
 * The inner one is narrower as well as smaller. Scaling a band down but not its
 * width makes the smaller shape read as fatter rather than nearer - the eye
 * takes band width to be a property of the object, so holding it constant
 * across two sizes flattens the pair into one plane.
 */
const CHEVRONS: readonly { readonly points: readonly Point[]; readonly width: number }[] = [
  { points: [[4.1, 4], [19.6, 16], [4.1, 28]], width: 6 },
  { points: [[15.6, 8.5], [25.6, 16], [15.6, 23.5]], width: 5 },
];

/**
 * How strongly each run is painted, in the order the runs are generated: the
 * outer chevron's upper arm and lower arm, then the inner chevron's.
 *
 * One colour at four strengths rather than four colours - the mark is
 * monochrome so it can be drawn in `currentColor` and inherit whichever of the
 * four themes is loaded. The outer chevron's leading arm takes full strength
 * because it carries the silhouette; everything else steps back from it.
 */
const TONES = [1, 0.62, 0.34, 0.78] as const;

function unit(a: Point, b: Point): Point {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const length = Math.hypot(dx, dy);
  return [dx / length, dy / length];
}

/**
 * Offset a polyline by `d` to its left, mitring at each joint.
 *
 * At a joint the offset corner sits along the angle bisector, at
 * `d / sin(theta / 2)` from the original vertex. That factor grows without
 * bound as the fold closes, so it is clamped: an unclamped mitre on a tight
 * fold throws a spike off the side of the mark, whereas being slightly
 * under-mitred at an angle nothing here uses is invisible.
 *
 * The two ends have only one direction to work with, so they take a plain
 * perpendicular offset - a square end, which is what a cut band has.
 */
function offsetPolyline(points: readonly Point[], d: number): Point[] {
  const out: Point[] = [];
  for (let i = 0; i < points.length; i++) {
    const incoming = i > 0 ? unit(points[i - 1], points[i]) : null;
    const outgoing = i < points.length - 1 ? unit(points[i], points[i + 1]) : null;

    if (!incoming || !outgoing) {
      const t = (incoming ?? outgoing)!;
      out.push([points[i][0] - t[1] * d, points[i][1] + t[0] * d]);
      continue;
    }

    // The bisector of the two edge normals, normalized.
    let bx = -incoming[1] - outgoing[1];
    let by = incoming[0] + outgoing[0];
    const length = Math.hypot(bx, by);
    bx /= length;
    by /= length;

    // The bisector's projection onto one edge normal - which is exactly the
    // sin(theta / 2) the mitre length divides by.
    const half = bx * -incoming[1] + by * incoming[0];
    const mitre = Math.min(1 / Math.max(half, 0.35), 2.9);
    out.push([points[i][0] + bx * d * mitre, points[i][1] + by * d * mitre]);
  }
  return out;
}

/** One closed quad per straight run, in order, sharing joint edges exactly. */
function bandRuns(points: readonly Point[], width: number): string[] {
  const left = offsetPolyline(points, width / 2);
  const right = offsetPolyline(points, -width / 2);
  const runs: string[] = [];
  for (let i = 0; i < points.length - 1; i++) {
    const corners: Point[] = [left[i], left[i + 1], right[i + 1], right[i]];
    runs.push(`M${corners.map(([x, y]) => `${R(x)} ${R(y)}`).join('L')}Z`);
  }
  return runs;
}

export interface MarkRun {
  /** A closed quad. Absolute coordinates only. */
  readonly d: string;
  /** How strongly to paint it, as a fraction of the mark's one colour. */
  readonly opacity: number;
}

export function brandMarkPaths(): MarkRun[] {
  const runs: string[] = [];
  for (const chevron of CHEVRONS) {
    runs.push(...bandRuns(chevron.points, chevron.width));
  }
  return runs.map((d, i) => ({ d, opacity: TONES[i] ?? 1 }));
}

/**
 * The box the drawn mark actually occupies.
 *
 * Computed from the generated geometry rather than declared beside it. The
 * mitre at each fold pushes the outer corner past the centreline by an amount
 * that depends on the angle, so the bounds are a RESULT of the drawing and
 * cannot be stated in advance without restating the mitre maths - at which
 * point there would be two versions of it to keep in agreement.
 */
export const MARK_BOUNDS = (() => {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const run of brandMarkPaths()) {
    // Every run is `M x y L x y L x y L x y Z`, absolute throughout, so reading
    // the numbers straight off the path is exact rather than an approximation.
    const numbers = run.d.match(/-?\d+(?:\.\d+)?/g)!.map(Number);
    for (let i = 0; i < numbers.length; i += 2) {
      minX = Math.min(minX, numbers[i]);
      maxX = Math.max(maxX, numbers[i]);
      minY = Math.min(minY, numbers[i + 1]);
      maxY = Math.max(maxY, numbers[i + 1]);
    }
  }
  return { minX: R(minX), minY: R(minY), maxX: R(maxX), maxY: R(maxY) };
})();

/**
 * The mark as a standalone SVG document.
 *
 * Used for `public/icon.svg` and as the source the rasteriser draws from, so
 * the tab, the PNGs and the Windows `.ico` are all the same drawing.
 *
 * `color` is a literal here rather than `currentColor`: a favicon has no
 * cascade to inherit from. The component is the one that inherits.
 */
export function brandMarkSvg(options: {
  color: string;
  /** Painted behind the mark. Omit for a transparent ground. */
  background?: string;
  /** Flatten every run to full strength - what the `.ico` renders. */
  flat?: boolean;
  /** Swap to `light` when the viewer's browser chrome is dark. */
  darkColor?: string;
}): string {
  const style = options.darkColor
    ? `<style>@media (prefers-color-scheme:dark){.nv{fill:${options.darkColor}}}</style>`
    : '';
  const runs = brandMarkPaths()
    .map((run) =>
      `<path class="nv" d="${run.d}" fill="${options.color}"`
      + `${options.flat ? '' : ` fill-opacity="${run.opacity}"`}/>`)
    .join('');
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${MARK_SIZE} ${MARK_SIZE}"`
    + ` width="${MARK_SIZE}" height="${MARK_SIZE}">`
    + style
    + (options.background
      ? `<rect width="${MARK_SIZE}" height="${MARK_SIZE}" fill="${options.background}"/>`
      : '')
    + runs
    + `</svg>`
  );
}
